mapper.select:
select distinct a.autoreview_id, a.autoreview_name, a.autoreview_type, a.create_time, a.update_time, a.create_user
from t_cfg_autoreview a left join t_cfg_autoreview_detail b on a.autoreview_id=b.autoreview_id where 1=1
 and b.auto_detail_type = 1 and b.ref_id=#{defectType, jdbcType=VARCHAR}
 and b.auto_detail_type = 2 and b.ref_id=#{alarmType, jdbcType=VARCHAR}
 and b.auto_detail_type = 3 and b.ref_id=#{deviceType, jdbcType=VARCHAR}
 and b.auto_detail_type = 4 and b.ref_name like concat ('%',#{deviceName, jdbcType=VARCHAR},'%')
 and b.auto_detail_type = 5 and b.ref_name like concat ('%',#{meteName, jdbcType=VARCHAR},'%')
 and b.auto_detail_type = 6 and b.ref_id=#{labelAttri, jdbcType=VARCHAR}
 and a.autoreview_name like concat('%',#{autoreviewName, jdbcType=VARCHAR},'%')
 and FIND_IN_SET(#{autoreviewType, jdbcType=VARCHAR}, a.autoreview_type) > 0
